from pathlib import Path
import json, hashlib, re
from datetime import datetime, UTC
from bs4 import BeautifulSoup

P = Path(__file__).parent
OWNER = '7b109880-ac40-447e-b2a6-f0ed1266ebac'
NOW = datetime.now(UTC).isoformat()
def write(name, x):
    (P/name).write_text(json.dumps(x, ensure_ascii=False, indent=2)+'\n')
def bind(p):
    p = Path(p)
    return {'path': str(p), 'sha256': hashlib.sha256(p.read_bytes()).hexdigest(), 'bytes': p.stat().st_size}

# These are actual public event dates, not advance calendar forecasts.
events, excluded = {}, []
for y in range(2015, 2021):
    f = P/'sources'/f'calendar_{y}.html'
    soup = BeautifulSoup(f.read_text(), 'html.parser')
    for a in soup.find_all('a', href=True):
        m = re.search(r'/pressreleases/monetary(\d{8})a\.htm$', a['href'])
        if not m or a.get_text(strip=True) != 'Statement':
            continue
        row = a.find_parent('div', class_='divided-row')
        heading = row.find_previous_sibling().get_text(' ', strip=True) if row is not None else a.find_parent('div').get_text(' ', strip=True)
        d = datetime.strptime(m[1], '%Y%m%d').date().isoformat()
        r = {'date': d, 'heading': heading, 'statement_url': 'https://www.federalreserve.gov'+a['href'], 'source': bind(f), 'published_at': d, 'visible_at': d+'T16:00:00 America/New_York', 'fetched_at': NOW, 'prompt_hash': None}
        if 'Meeting' in heading and 'conference' not in heading.lower() and 'notation' not in heading.lower() and datetime.strptime(d,'%Y-%m-%d').weekday()<5:
            events[d] = r
        else:
            excluded.append(r)
soup = BeautifulSoup((P/'sources/calendar_current.html').read_text(), 'html.parser')
for row in soup.select('.fomc-meeting'):
    for a in row.find_all('a', href=True):
        m = re.search(r'/pressreleases/monetary(\d{8})a\.htm$', a['href'])
        if not m:
            continue
        d = datetime.strptime(m[1], '%Y%m%d').date().isoformat()
        heading = row.get_text(' ', strip=True)
        r = {'date': d, 'heading': heading, 'statement_url': 'https://www.federalreserve.gov'+a['href'], 'source': bind(P/'sources/calendar_current.html'), 'published_at': d, 'visible_at': d+'T16:00:00 America/New_York', 'fetched_at': NOW, 'prompt_hash': None}
        if d > '2026-10-12' or 'unscheduled' in heading.lower() or 'notation' in heading.lower() or 'conference call' in heading.lower() or datetime.strptime(d,'%Y-%m-%d').weekday()>=5:
            excluded.append(r)
        else:
            events[d] = r
write('calendar-packet.json', {'schema_version': 1, 'events': [events[d] for d in sorted(events)], 'excluded': excluded, 'scope': 'Past scheduled statements only; unscheduled calls excluded; no advance-release-vintage claim. No nonexistent canceled March2020 meeting.'})

